parameters.text:
=FocusTrack — {{ $json.business.name }} — {{ new Date($json.date).toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}) }}

{{ (() => {
  const t = $json.totals;
  const mins = m => m >= 60 ? (m % 60 ? Math.floor(m/60)+'h '+(m%60)+'m' : Math.floor(m/60)+'h') : m+'m';
  const L = [];

  L.push('THE DAY IN ONE LINE');
  L.push(t.activePeople + ' of ' + t.people + ' people worked. Planned ' + mins(t.plannedMinutes) + ', logged ' + mins(t.loggedMinutes) + ' across ' + t.sessions + ' sessions.');
  if (t.assignedTotal) L.push('Of the work you assigned, ' + t.assignedDone + ' of ' + t.assignedTotal + ' got done.');
  if (t.distractions) L.push(t.distractions + ' interruption' + (t.distractions === 1 ? '' : 's') + ' logged.');
  L.push('');

  for (const p of $json.people) {
    if (p.quiet) continue;
    L.push('----------------------------------------');
    L.push(p.name + (p.team ? '  (' + p.team + ')' : ''));
    if (p.planned) {
      L.push('  planned ' + mins(p.plannedMinutes) + '   logged ' + mins(p.loggedMinutes) + '   ' + p.done + ' of ' + p.planned + ' tasks done');
      if (p.assignedTotal) L.push('  your tasks: ' + p.assignedDone + ' of ' + p.assignedTotal + ' done');
    } else {
      L.push('  logged ' + mins(p.loggedMinutes) + ' across ' + p.sessions + ' session' + (p.sessions === 1 ? '' : 's') + ' — nothing was planned');
    }
    L.push('');
    for (const i of p.items) {
      const mark = i.status === 'done' ? '[x]' : (i.status === 'skipped' ? '[-]' : '[ ]');
      let line = '  ' + mark + ' ' + i.title;
      const bits = [];
      bits.push(mins(i.estimateMin) + ' planned');
      if (i.actualMin > 0) bits.push(mins(i.actualMin) + ' actual');
      if (i.assignedBy) bits.push('you assigned');
      if (i.movedCount > 0) bits.push('moved ' + i.movedCount + 'x');
      line += '   (' + bits.join(', ') + ')';
      L.push(line);
      if (i.status === 'skipped' && i.skipReason) L.push('        skipped: ' + i.skipReason);
    }
    if (p.unplannedSessions && p.items.length) {
      L.push('  + ' + mins(p.unplannedMinutes) + ' on ' + p.unplannedSessions + ' unplanned session' + (p.unplannedSessions === 1 ? '' : 's'));
    }
    L.push('');
  }

  const quiet = $json.people.filter(p => p.quiet);
  if (quiet.length) {
    L.push('----------------------------------------');
    L.push('NO ACTIVITY AT ALL');
    L.push('  ' + quiet.map(p => p.name).join(', '));
    L.push('  Nothing planned and no timer use. May be off today.');
    L.push('');
  }

  L.push('----------------------------------------');
  L.push('Dashboard: https://focus.u2berclub.com/' + $json.business.slug + '/admin');
  L.push('To change the time this arrives, or switch it off: Settings tab.');
  return L.join('\n');
})() }}
